import React from "react"
import ReactDOM from "react-dom/client"
import "./style.css"

import one from "./Assest/images/one.jpg"
import two from "./Assest/images/two.jpg"
import three from "./Assest/images/three.jpg"

const root = ReactDOM.createRoot(document.getElementById("root"))

//Navbar component
function Navbar() {
  return (
    <nav>
      <h1>PERFUMY</h1>
      <ul>
        <li>Home|</li>
        <li>Produts|</li>
        <li>About Us|</li>
        <li>Contact Us</li>
      </ul>
    </nav>
  )
}

//Search Component

function Search() {
  return (
    <div className="searchbar">
      <input type="text" placeholder="Search" />
    </div>
  )
}

//Product component

function Product() {
  return (
    <div class="products">

      <div class="box">

        <img src={one}></img>
        <p>Fogg Wood Extreme, Eau De Parfum, Long-lasting Perfume, 100ml</p>
      </div>


      <div class="box">
        <img src={two}></img>
        <p>Fogg Wood Extreme, Eau De Parfum, Long-lasting Perfume, 100ml</p>
      </div>
      <div class="box">
        <img src={three} alt="Designs Club"></img>
        <p>Designer Club-Be Spoke by Perfume Lounge Men's Perfume | Premium Long Lasting Perfume</p>
      </div>
    </div>
  )
}


function About() {
  return (
    <div style={{ textAlign: "center" }}>
      <div class="about" style={{ marginTop: "10px", textAlign: "center" }}>
        <h1>About Us</h1>
        <p>The standard chunk of Lorem Ipsum used since the 1500s is reproduced below for those interested. Sections 1.10.32 and 1.10.33 from "de Finibus Bonorum et Malorum" by Cicero are also reproduced in their exact original form, accompanied by English versions from the 1914 translation by H. Rackham.</p>
      </div>
    </div>
  )
}


//
function footer() {
  return (
<div>
    <div class="contact">
        <h3>Contact</h3>
        <p style={{marginTop: "5px"}}>+91 3478631928 <br></br>
        </p>

      </div>
      <p style={{fontSize: "small", padding: "20px",color: "grey"}}>
      </p>
</div>


  )
}
root.render(
  <div>
    <Navbar></Navbar>
    <Search></Search>
    <Product></Product>
    <About></About>
    <footer></footer>
  </div>)
